#!/bin/bash
set -euo pipefail
umask 077
/usr/bin/python3 -I -s -B - <<'PY'
import base64,hashlib,io,json,os,sys,tarfile
from pathlib import Path
def install():
    p=Path('/project/community/jjyeung/ae63d9b7124fc')
    source=Path('/project/community/jjyeung/ac794e028b16f/8.tgz')
    blob=base64.b64decode('',validate=True)
    if hashlib.sha256(blob).hexdigest()!='90a1baccf1e033dcd099d8f4d33b21a22b8f97fa8c5ff7a34a80a6443e8855f4':raise ValueError('E40')
    with tarfile.open(fileobj=io.BytesIO(blob),mode='r:gz') as t:
        members=t.getmembers()
        if len(members)!=6 or set(m.name for m in members)!=set(['0.py', '1.json', '2.py', '9.py', 'BATCH.sh', '3.json']) or any(not m.isfile() for m in members):raise ValueError('E41')
        data={m.name:t.extractfile(m).read() for m in members}
    pins=json.loads(data['3.json'])
    if set(pins)!=set(['0.py', '1.json', '2.py', '9.py', 'BATCH.sh', '3.json'])-{'3.json'}|{'8.tgz'}:raise ValueError('E43')
    for n in ['0.py', '1.json', '2.py', '9.py', 'BATCH.sh', '3.json']:
        if n!='3.json' and hashlib.sha256(data[n]).hexdigest()!=pins[n]:raise ValueError('E43')
    if p.exists():raise ValueError('E44')
    if source.stat().st_size!=44374984:raise ValueError('E45')
    with source.open('rb') as f:
        if hashlib.file_digest(f,'sha256').hexdigest()!=pins['8.tgz']:raise ValueError('E46')
    p.mkdir(mode=0o700)
    os.link(source,p/'8.tgz')
    if not os.path.samefile(source,p/'8.tgz'):raise ValueError('E47')
    for n,b in data.items():
        with (p/n).open('xb') as f:f.write(b)
    print(sum(map(len,data.values())))
try:
    install()
except Exception as e:
    code=e.args[0] if e.args and isinstance(e.args[0],str) and e.args[0] in ('E40','E41','E43','E44','E45','E46','E47') else 'E49'
    print(code,file=sys.stderr)
    raise SystemExit(1)
PY
